ValidationRule.errorConditionFormula:
IF(
  $UserRole.Name = "System Administrator",
  FALSE,
  AND(
    /* 只在 CA（當前或前一筆）啟動 */
    OR(
      TEXT(Approval_Status__c) = "Conditionally Approved",
      TEXT(PRIORVALUE(Approval_Status__c)) = "Conditionally Approved"
    ),
    OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)),

/* ★ 將所有「DR → CA」交回 S3（避免攔到 S3-9 / S3-10 的路徑） */
NOT(
  OR(
    /* S3-9：Reapplied|IP → Reapplied|CA（EHD） */
    AND(
      TEXT(PRIORVALUE(Status__c)) = "Reapplied",
      TEXT(PRIORVALUE(Approval_Status__c)) = "In Progress",
      TEXT(Status__c) = "Reapplied",
      TEXT(Approval_Status__c) = "Conditionally Approved"
    ),
    /* S3-10：Reapplied|CA → Replied|CA（RMS） */
    AND(
      TEXT(PRIORVALUE(Status__c)) = "Reapplied",
      TEXT(PRIORVALUE(Approval_Status__c)) = "Conditionally Approved",
      TEXT(Status__c) = "Replied",
      TEXT(Approval_Status__c) = "Conditionally Approved"
    ),
    /* 保險絲：任何 DR → CA 一律交回 S3 */
    AND(
      TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required",
      TEXT(Approval_Status__c) = "Conditionally Approved"
    )
  )
),

    /* 不在 S4 白名單才報錯（維持原本清單） */
    NOT(
      CONTAINS(
        ";" &
        "New|New>In Progress|New;" &
        "In Progress|New>In Progress|In Progress;" &
        "In Progress|In Progress>In Progress|Conditionally Approved;" &
        "In Progress|Conditionally Approved>Replied|Conditionally Approved;" &
        "Replied|Conditionally Approved>Closed|Conditionally Approved;" &
        ";",
        ";" &
        TEXT(PRIORVALUE(Status__c)) & "|" & TEXT(PRIORVALUE(Approval_Status__c)) &
        ">" &
        TEXT(Status__c) & "|" & TEXT(Approval_Status__c) & ";"
      )
    )
  )
)
